SELECT AVG(CAST(metric_0001 AS DOUBLE)) AS avg_metric_0001, AVG(CAST(metric_0250 AS DOUBLE)) AS avg_metric_0250, AVG(CAST(metric_0500 AS DOUBLE)) AS avg_metric_0500, AVG(CAST(metric_0750 AS DOUBLE)) AS avg_metric_0750, AVG(CAST(metric_1000 AS DOUBLE)) AS avg_metric_1000 FROM wide1000 WHERE time >= '2024-12-31' AND time < '2025-01-01'
